from author_tools import *
N(bank,6,226,C,'Цифры числа и ограничения на запись','15',[
('6-digits-thousands-value','В числе 507208 найдите цифру в разряде тысяч.',7,'Разряды справа: единицы 8, десятки 0, сотни 2, тысячи 7.','(507208//1000)%10','b'),
('6-digits-leading-zero','Из цифр 0, 3, 7 составьте наименьшее трёхзначное число, используя каждую один раз.',307,'Сотни не могут быть нулём, ставим 3. Из оставшихся цифр меньшую 0 ставим в десятки, получаем 307.','min(100*a+10*b+c for a,b,c in permutations([0,3,7]) if a)','b'),
('6-digits-remove-position','Из числа 48326 вычеркнули цифру сотен, не меняя порядка остальных. Какое число получилось?',4826,'Цифра сотен 3. Оставшиеся цифры образуют 4826.','int(str(48326)[:2]+str(48326)[3:])','m'),
('6-digits-product-tens','Найдите наименьшее двузначное число, произведение цифр которого равно 12.',26,'Пары цифр с произведением 12: 2 и 6, 3 и 4. Минимальное число получается с десятком 2: 26.','min(n for n in range(10,100) if (n//10)*(n%10)==12)','m'),
('6-digits-two-different-same-sum','Сколько двузначных чисел с различными цифрами имеют сумму цифр 8?',7,'Десятки могут быть 1,2,3,5,6,7,8. Также 4 и 4 дают равные цифры и не подходят. Всего семь.','sum(n//10+n%10==8 and n//10!=n%10 for n in range(10,100))','h'),
('6-digits-divisor-from-permutation','Из цифр 1, 2, 4 без повторений составили трёхзначное число, кратное 4. Найдите сумму всех таких чисел.',536,'Делятся на 4 окончания 12 и 24. Получаются числа 412 и 124, сумма 536.','sum(100*a+10*b+c for a,b,c in permutations([1,2,4]) if (10*b+c)%4==0)','h'),
('6-digits-leading-added','Слева от двузначного числа приписали цифру 3. Число увеличилось на сколько?',300,'Старые десятки и единицы не изменились. Появилось 3 сотни, прибавка равна 300.','int("3"+str(42))-42','m'),
('6-digits-zero-between','В двузначное число 47 между цифрами вставили 0. Во сколько раз изменилось значение цифры 4?',10,'Цифра 4 перешла из десятков в сотни. Её разрядное значение выросло с 40 до 400, то есть в 10 раз.','400/40','m'),
('6-digits-max-distinct-even','Найдите наибольшее четырёхзначное чётное число из цифр 1, 4, 6, 9 без повторений.',9614,'Нужно оставить чётную цифру в единицах. При окончании 4 можно поставить слева 961, получая 9614; при окончании 6 максимум 9416 меньше.','max(1000*a+100*b+10*c+d for a,b,c,d in permutations([1,4,6,9]) if d%2==0)','h'),
('6-digits-sum-product-reconstruct','Две ненулевые цифры имеют сумму 9 и произведение 20. Найдите разность большего и меньшего двузначных чисел, составленных из этих цифр.',9,'Цифры 4 и 5. Из них получаются 45 и 54, разность 9.','next((10*b+a)-(10*a+b) for a in range(1,10) for b in range(a+1,10) if a+b==9 and a*b==20)','h'),
('6-digits-palindrome-count','Сколько трёхзначных чисел одинаково читаются слева направо и справа налево и делятся на 5?',10,'У такого числа сотни равны единицам. Для делимости на 5 последняя цифра 0 или 5, но сотни ненулевые, значит крайние цифры 5. Средняя цифра любая: десять чисел.','sum(str(n)==str(n)[::-1] and n%5==0 for n in range(100,1000))','s'),
('6-digits-repeated-nine-divisor','Трёхзначное число имеет три одинаковые ненулевые цифры и делится на 9. Сколько таких чисел?',3,'Число имеет вид 111d. Его сумма цифр 3d должна делиться на 9. Подходят d = 3, 6, 9, всего три числа.','sum(n%9==0 for n in [111*d for d in range(1,10)])','s')])
N(bank,6,227,C,'Буквенные выражения и применение формул','16',[
('6-letter-substitution-two','Найдите значение 5a − 2b при a = 3, b = −4.',23,'Подставляем: 15 − (−8) = 23.','5*3-2*(-4)','b'),
('6-formula-perimeter-square-inverse','По формуле P = 4a найдите a при P = 31,2 см.',7.8,'Делим периметр на 4: a = 7,8 см.','F("31.2")/4','b'),
('6-letter-constant-after-reduce','Вычислите 4(a + 3) − 4a при a = 17,8.',12,'Распределительный закон даёт 4a + 12 − 4a = 12.','4*(F("17.8")+3)-4*F("17.8")','m'),
('6-formula-temperature','Температура F по шкале Фаренгейта связана с температурой C формулой F = 9C/5 + 32. Найдите F при C = −10.',14,'Вычисляем 9 · (−10)/5 + 32 = −18 + 32 = 14.','9*(-10)/5+32','m'),
('6-letter-distributive-missing','Для любых a верно 7(a + 2) = 7a + k. Найдите k.',14,'Раскрываем скобки: 7a + 14. Следовательно, k = 14.','7*(5+2)-7*5','m'),
('6-formula-unknown-component','По формуле s = vt найдите t в часах, если s = 42 км, v = 5,25 км/ч.',8,'Время t = s/v = 42 : 5,25 = 8 часов.','42/F("5.25")','m'),
('6-letter-hidden-negative','Число a отрицательно, |a| = 6. Найдите 2a − |a|.',-18,'Из отрицательности a = −6. Получаем −12 − 6 = −18.','2*(-6)-abs(-6)','h'),
('6-formula-rectangle-sum-known','Известно a + b = 13. Найдите значение 6a + 6b − 5.',73,'Общий множитель 6 даёт 6(a + b) − 5 = 78 − 5 = 73.','6*13-5','h'),
('6-letter-difference-known','Известно a − b = −4. Найдите 3b − 3a + 2.',14,'3b − 3a = −3(a − b) = 12. Добавляем 2 и получаем 14.','-3*(-4)+2','h'),
('6-formula-cost-rate-double','Стоимость поездки задаётся формулой C = 80 + 12n, где n — число километров. На сколько рублей увеличится стоимость при росте n с 5 до 9?',48,'Постоянная часть 80 сокращается. Изменение стоимости 12 · (9 − 5) = 48 рублей.','(80+12*9)-(80+12*5)','m'),
('6-letter-symmetric-expression','Сумма a + b равна 7, сумма b + c равна 11, сумма a + c равна 10. Найдите a + b + c.',14,'В сумме трёх равенств каждое число учтено дважды. Поэтому искомая сумма (7 + 11 + 10)/2 = 14.','(7+11+10)/2','s'),
('6-formula-composition-reverse','Машина заменяет число n на 3n − 2. Одно число пропустили через неё дважды и получили 37. Найдите исходное число.',5,'Обратный ход: перед вторым запуском было (37 + 2)/3 = 13. Исходное число (13 + 2)/3 = 5.','((37+2)/3+2)/3','s')])
N(bank,6,228,V,'Приближённые измерения окружности и круга','17',[
('6-circle-approx-circumference','Для приближённого расчёта примите длину окружности равной 3,14 диаметра. Диаметр 10 см. Найдите длину окружности в сантиметрах.',31.4,'По указанному правилу 3,14 · 10 = 31,4 см.','F("3.14")*10','b'),
('6-circle-approx-area','Для приближённого расчёта площади круга используйте S = 3,14r². Радиус 5 см. Найдите площадь в см².',78.5,'S = 3,14 · 25 = 78,5 см².','F("3.14")*5**2','b'),
('6-circle-wheel-revolutions','Длина окружности колеса 1,5 м. Сколько полных оборотов оно сделает на пути 45 м без проскальзывания?',30,'За оборот проходит 1,5 м. Число оборотов 45 : 1,5 = 30.','45/F("1.5")','m'),
('6-circle-semicircle-boundary','Диаметр полукруглой детали 8 см. Примите длину полной окружности равной 3,14 диаметра. Найдите периметр детали в сантиметрах.',20.56,'Полукруглая дуга равна половине окружности: 12,56 см. Добавляем диаметр 8 см, периметр 20,56 см.','F("3.14")*8/2+8','h'),
('6-circle-ring-area','Внешний радиус круглой рамки 5 см, внутренний 3 см. По правилу S = 3,14r² найдите площадь рамки в см².',50.24,'Площадь рамки — разность площадей кругов: 3,14 · (25 − 9) = 50,24 см².','F("3.14")*(5**2-3**2)','m'),
('6-circle-quarter-arc','Круглая дорожка имеет длину 120 м. Бегун прошёл четверть круга, затем ещё треть круга в том же направлении. Сколько метров он прошёл?',70,'Всего пройдено 1/4 + 1/3 = 7/12 круга. Длина 120 · 7/12 = 70 м.','120*(F(1,4)+F(1,3))','m'),
('6-circle-rope-margin','Круглую клумбу радиуса 2 м нужно оградить лентой, добавив 0,5 м на соединение. Используйте длину окружности 2 · 3,14r. Сколько метров ленты нужно?',13.06,'Окружность 12,56 м. С припуском нужно 13,06 м.','2*F("3.14")*2+F("0.5")','m'),
('6-circle-inverse-diameter','Измеренная длина окружности 62,8 см. Если длина окружности равна 3,14 диаметра, найдите радиус в сантиметрах.',10,'Диаметр 62,8 : 3,14 = 20 см. Радиус вдвое меньше: 10 см.','F("62.8")/F("3.14")/2','h'),
('6-circle-square-comparison','Круг радиуса 3 см вписан в квадрат со стороной 6 см. По правилу S = 3,14r² найдите площадь части квадрата вне круга в см².',7.74,'Площадь квадрата 36, круга 28,26. Разность 7,74 см².','6**2-F("3.14")*3**2','h'),
('6-circle-one-meter-radius-growth','Два круга имеют радиусы 4 и 5 см. Во сколько раз площадь второго больше? Используйте одну и ту же формулу S = 3,14r².',1.5625,'Множитель 3,14 сокращается. Отношение площадей 25/16 = 1,5625.','F(5**2,4**2)','h'),
('6-circle-rope-raise','Лента длиной 31,4 м плотно охватывала круг. Её удлинили на 6,28 м и снова сделали круг. На сколько метров вырос радиус? Используйте C = 2 · 3,14r.',1,'Изменение длины равно 2 · 3,14 · изменению радиуса. Поэтому прирост радиуса 6,28/6,28 = 1 м.','F("6.28")/(2*F("3.14"))','s'),
('6-circle-two-turns-meet','Две метки движутся по окружности длиной 60 см из одной точки в противоположных направлениях со скоростями 7 и 5 см/с. Сколько раз за первые 20 секунд после старта они совпадут, включая момент 20 с?',4,'Относительная скорость 12 см/с, совпадения каждые 5 секунд. Это моменты 5,10,15,20 — четыре раза.','sum(((7+5)*t)%60==0 for t in range(1,21))','s')])
N(bank,6,229,W,'Время, календарь и циклические расписания','16',[
('6-time-overnight-duration','Поезд отправился в 22:40 и прибыл на следующий день в 6:15. Сколько минут он был в пути?',455,'До полуночи 80 минут, после полуночи 375. Всего 455 минут.','24*60-(22*60+40)+(6*60+15)','b'),
('6-calendar-week-shift','Сегодня вторник. Какой по счёту день недели будет через 100 дней? Понедельник считайте первым.',4,'100 даёт остаток 2 при делении на 7. Через два дня после вторника четверг, четвёртый день.','(2-1+100)%7+1','b'),
('6-time-clock-fast','Часы спешат на 3 минуты за каждые сутки. Их точно установили в понедельник в полдень. На сколько минут они будут спешить в пятницу в полдень?',12,'Прошли четыре полных суток. Ошибка 4 · 3 = 12 минут.','4*3','m'),
('6-calendar-inclusive-count','Занятия проходят ежедневно с 12 по 27 июня включительно. Сколько занятий?',16,'При включении обоих концов число дат равно 27 − 12 + 1 = 16.','len(range(12,28))','m',{'tricky':True}),
('6-time-bus-departures','Автобусы отправляются каждые 18 минут начиная с 7:10. Сколько отправлений будет до 9:00 включительно?',7,'Промежуток 110 минут. После первого отправления помещаются ещё 6 интервалов по 18 минут; всего 7.','1+(9*60-(7*60+10))//18','m'),
('6-time-running-clock-gap','Одни часы идут точно, другие за час отстают на 2 минуты. В 8:00 показания совпали. Что покажут вторые часы, когда точные покажут 14:00? В ответе число минут после 13:00.',48,'За 6 часов отставание 12 минут. Вторые часы покажут 13:48, то есть 48 минут после 13:00.','(14*60-6*2)-13*60','h'),
('6-calendar-31day-weekends','В месяце 31 день, первое число — пятница. Сколько в этом месяце суббот и воскресений вместе?',10,'На четыре полные недели приходится 8 выходных. Последние три дня — пятница, суббота, воскресенье, значит ещё два выходных.','sum((4+d)%7 in [5,6] for d in range(31))','h'),
('6-time-work-rest-cycle','Робот работает 7 минут, отдыхает 3 минуты и повторяет цикл. Сколько минут работы он выполнит за первые 38 минут с момента включения?',28,'Три полных цикла дают 21 минуту работы. В оставшихся 8 минутах есть 7 минут работы и 1 отдыха; всего 28.','sum(t%10<7 for t in range(38))','h'),
('6-calendar-double-duty','Маша дежурит через каждые 4 дня, Коля — через каждые 6 дней. Они дежурят вместе 1 октября. Какого числа октября будет следующее совместное дежурство?',13,'Промежуток между совместными дежурствами НОК(4,6) = 12 дней. Следующая дата 1 + 12 = 13 октября.','1+lcm(4,6)','m'),
('6-time-zones-east-west','В городе A 18:30, в городе B одновременно 14:30. Самолёт вылетел из A в 20:00 и летел 3 часа. Какое местное время B в момент прилёта? В ответе число часов после полуночи.',19,'B отстаёт от A на 4 часа. В момент прилёта в A 23:00, в B 19:00.','20+3-(18.5-14.5)','h'),
('6-time-slow-fast-meet-again','Двое часов показывают 12:00. Первые за реальный час спешат на 1 минуту, вторые отстают на 1 минуту. Через сколько реальных часов разница показаний впервые станет 1 час?',30,'Разница увеличивается на 2 минуты в час. Для 60 минут нужно 60 : 2 = 30 часов.','60/(1+1)','s'),
('6-calendar-weekday-extras','В месяце 31 день. Пятниц больше, чем воскресений, а сред столько же, сколько четвергов. Каким днём начался месяц? Понедельник считайте первым.',3,'Пять раз встречаются только три последовательных дня от первого числа. Чтобы пятниц было пять, а воскресений четыре, начало возможно в среду или четверг. При начале в четверг сред четыре, четвергов пять. Значит месяц начался в среду.','next(s+1 for s in range(7) if sum((s+d)%7==4 for d in range(31))>sum((s+d)%7==6 for d in range(31)) and sum((s+d)%7==2 for d in range(31))==sum((s+d)%7==3 for d in range(31)))','s'),])
N(bank,6,230,W,'Порядок, сравнение и восстановление расположения','16',[
('6-order-three-heights','Аня выше Бори, Боря выше Веры. Кто самый низкий? Введите 1 для Ани, 2 для Бори, 3 для Веры.',3,'Из двух сравнений следует Аня выше Бори выше Веры. Самая низкая Вера.','min([(3,1),(2,2),(1,3)])[1]','b'),
('6-order-race-position','Перед бегуном 5 участников, позади 8. Сколько всего участников забега?',14,'Учитываем 5 впереди, самого бегуна и 8 позади: 14.','5+1+8','b'),
('6-order-queue-two-counts','В очереди Дима шестой от начала и девятый от конца. Сколько человек в очереди?',14,'Дима вошёл в оба счёта. Складываем 6 и 9 и вычитаем одно повторение: 14.','6+9-1','m'),
('6-order-middle-four','Четыре числа различны. a < b, c < a, b < d. Сколько чисел больше a?',2,'Порядок c < a < b < d. Больше a числа b и d: два числа.','sum(v>2 for v in [2,3,1,4])','m'),
('6-order-overtaking-second','Бегун обогнал участника, который занимал второе место. Какое место он теперь занимает?',2,'Он занял место обогнанного участника, то есть второе. Лидер всё ещё впереди.','[1,2,3].index(2)+1','m',{'tricky':True}),
('6-order-books-three-conditions','Три книги A,B,C стоят в ряд. A не с краю, B левее C. Какой номер позиции занимает C?',3,'A стоит посередине. Из двух свободных мест B занимает левое, C правое, то есть третье.','next(p.index("C")+1 for p in permutations("ABC") if p.index("A")==1 and p.index("B")<p.index("C"))','h'),
('6-order-five-comparisons','У пяти участников разные результаты. A лучше C, C лучше E, B лучше A, D хуже E. Какое место занимает C?',3,'Полный порядок B, A, C, E, D. C занимает третье место.','next(p.index("C")+1 for p in permutations("ABCDE") if p.index("A")<p.index("C")<p.index("E")<p.index("D") and p.index("B")<p.index("A"))','h'),
('6-order-number-of-arrangements','В ряд ставят три разные фигуры. Круг обязан стоять левее квадрата, положение треугольника свободно. Сколько расстановок возможно?',3,'Без ограничений шесть расстановок. В половине круг левее квадрата; можно также перечислить ККвТ, КТКв, ТККв. Всего три.','sum(p.index("O")<p.index("S") for p in permutations("OST"))','h'),
('6-order-queue-between','В очереди из 20 человек Оля седьмая от начала, Петя пятый от конца. Сколько людей между ними?',8,'Петя занимает 20 − 5 + 1 = 16-е место от начала. Между 7-м и 16-м местами восемь человек.','(20-5+1)-7-1','m'),
('6-order-circular-neighbors','Шесть человек сели вокруг круглого стола. Сколько пар соседей за столом?',6,'У каждого два соседа, всего 12 упоминаний соседства. Каждая пара посчитана дважды, значит пар 6.','6*2//2','h'),
('6-order-swap-rank','В шеренге 15 человек Миша стоял пятым слева. Он поменялся местами с человеком, который был третьим справа. Каким справа стал Миша?',3,'Он занял ровно место человека, бывшего третьим справа. Значит теперь сам третий справа.','15-(15-3+1)+1','h',{'tricky':True}),
('6-order-all-possible-top','A выше B, C выше B, D ниже B. Других сведений нет. Сколько человек могут оказаться самыми высокими?',2,'B не самый высокий, D тем более. Самым высоким может быть A или C, их взаимный порядок неизвестен.','len({p[0] for p in permutations("ABCD") if p.index("A")<p.index("B") and p.index("C")<p.index("B")<p.index("D")})','s')])
N(bank,6,231,W,'Весы, тара и равновесие','16',[
('6-balance-two-packs','Два одинаковых пакета весят вместе 1,7 кг. Сколько граммов весит один?',850,'Один пакет весит 0,85 кг, это 850 г.','F("1.7")*1000/2','b'),
('6-balance-tare-from-full','Полная коробка весит 3,4 кг, содержимое 2,8 кг. Найдите массу пустой коробки в килограммах.',.6,'Масса тары — разность полной массы и содержимого: 0,6 кг.','F("3.4")-F("2.8")','b'),
('6-balance-equation-fruit','На весах три одинаковых яблока уравновесили яблоко и гирю 240 г. Сколько граммов весит яблоко?',120,'Убираем по яблоку с обеих чаш. Два яблока весят 240 г, одно 120 г.','240/(3-1)','m'),
('6-balance-three-object-types','Две груши весят как три сливы, одна груша весит 90 г. Сколько граммов весят пять слив?',300,'Две груши весят 180 г, слива 60 г. Пять слив весят 300 г.','2*90/3*5','m'),
('6-balance-water-half','Полная бутылка воды весит 900 г, бутылка с половиной воды — 500 г. Сколько граммов весит пустая бутылка?',100,'Половина воды весит 400 г. Вся вода 800 г, тара 900 − 800 = 100 г.','2*500-900','h'),
('6-balance-box-count','Ящик с 12 одинаковыми деталями весит 7 кг, с 7 такими деталями — 4,5 кг. Сколько граммов весит одна деталь?',500,'Разница масс 2,5 кг соответствует 5 деталям. Одна весит 0,5 кг = 500 г.','(7-F("4.5"))*1000/(12-7)','h'),
('6-balance-opposite-pan','На одной чаше 5 одинаковых кубиков и гиря 20 г, на другой — 3 таких кубика и гиря 100 г. Весы в равновесии. Найдите массу кубика в граммах.',40,'Убираем три кубика и 20 г с обеих чаш. Два кубика весят 80 г, один 40 г.','(100-20)/(5-3)','m'),
('6-balance-cut-bar','Брусок весит 840 г. Его разрезали на три части в отношении 2 : 3 : 7. На сколько граммов тяжёлая часть тяжелее лёгкой?',350,'В одной доле 70 г. Разность 5 долей равна 350 г.','840/(2+3+7)*(7-2)','m'),
('6-balance-scale-offset','Неисправные весы к любой массе прибавляют 120 г. Коробку они показали как 830 г. Найдите настоящую массу в граммах.',710,'Нужно вычесть постоянную ошибку: 830 − 120 = 710 г.','830-120','m'),
('6-balance-same-offset-total','Весы прибавляют к каждой отдельной нагрузке 50 г. Три пакета по одному показали суммарно 1200 г. Сколько покажут весы, если положить три пакета вместе?',1100,'Настоящая суммарная масса 1200 − 150 = 1050 г. При совместном взвешивании ошибка добавится один раз, показание 1100 г.','1200-3*50+50','h'),
('6-balance-four-coins-heavier','Среди 4 одинаковых на вид монет одна тяжелее, остальные весят одинаково. Какое минимальное число взвешиваний на чашечных весах гарантирует находку тяжёлой?',2,'Одно взвешивание имеет три исхода и не различит четыре возможности. За два можно: сравнить две пары, затем две монеты тяжёлой пары.','ceil(log(4,3))','s'),
('6-balance-nine-coins-light','Среди 9 монет одна легче, остальные равны. Какое минимальное число взвешиваний на чашечных весах гарантирует её нахождение?',2,'Сравниваем две тройки и определяем подозрительную тройку. В ней сравнением двух монет определяем лёгкую. Меньше двух взвешиваний не различит 9 вариантов.','ceil(log(9,3))','s')])
N(bank,6,232,W,'Выбор плана и минимальные расходы','16',[
('6-plan-hourly-rent','Прокат стоит 150 рублей в час. Сколько рублей стоит 2,5 часа без округления времени?',375,'Стоимость 150 · 2,5 = 375 рублей.','150*F("2.5")','b'),
('6-plan-route-min','До библиотеки есть маршруты длиной 1,8 км, 2,1 км и 1,6 км. Сколько метров составляет кратчайший?',1600,'Минимальная длина 1,6 км. Это 1600 м.','min(F("1.8"),F("2.1"),F("1.6"))*1000','b'),
('6-plan-minute-billing','За каждый начатый час проката платят 180 рублей. Пользовались 2 часа 5 минут. Сколько рублей нужно заплатить?',540,'Начался третий час. Оплачиваются три часа: 540 рублей.','ceil(F(125,60))*180','m'),
('6-plan-two-tariffs','Тариф A: 100 рублей и 8 рублей за минуту. Тариф B: 40 рублей и 12 рублей за минуту. Сколько рублей сэкономит выбор более дешёвого тарифа для 20 минут?',20,'A стоит 260 рублей, B 280. Экономия 20 рублей.','abs((100+8*20)-(40+12*20))','m'),
('6-plan-trip-tickets','Один билет стоит 55 рублей, билет на 10 поездок — 480 рублей. Нужно 14 поездок. Найдите наименьшую стоимость в рублях, если лишние поездки допустимы.',700,'Один пакет и 4 разовых стоят 700 рублей. Только разовые стоят 770, два пакета 960. Минимум 700.','min(480*a+55*b for a in range(3) for b in range(15) if 10*a+b>=14)','h'),
('6-plan-bus-capacity','Нужно перевезти 74 человека. Автобус на 40 мест стоит 6000 рублей, на 25 мест — 4200. Найдите минимальную стоимость аренды, если автобусы можно сочетать.',12000,'Два больших автобуса стоят 12000 и дают 80 мест. Три малых стоят 12600; один большой и два малых — 14400. Дешевле двух больших нет.','min(6000*a+4200*b for a in range(4) for b in range(4) if 40*a+25*b>=74)','h'),
('6-plan-delivery-free','Товар стоит 750 рублей, доставка 250. При заказе от 900 рублей доставка бесплатна. Покупатель добавляет второй нужный товар за 180 рублей. На сколько рублей уменьшится итоговый платёж?',70,'Первоначальный платёж 1000 рублей. Новый заказ 930 рублей проходит порог бесплатной доставки. Платёж уменьшился на 70.','750+250-(750+180)','m',{'tricky':True}),
('6-plan-paint-waste','Нужно 7,5 л краски. Банки по 2 л стоят 440 рублей, по 5 л — 1000. Какова наименьшая стоимость покупки в рублях?',1760,'Четыре малые банки дают 8 л за 1760 рублей. С одной большой нужны две малые: 1880 рублей, две большие стоят 2000 рублей. Минимум 1760.','min(440*a+1000*b for a in range(6) for b in range(3) if 2*a+5*b>=F("7.5"))','h'),
('6-plan-cable-cutting','Кабель продают целыми метрами. Для четырёх подключений нужно по 1,35 м и ещё 0,8 м общего запаса. Сколько метров минимум купить?',7,'Требуется 4 · 1,35 + 0,8 = 6,2 м. Покупают не менее 7 целых метров.','ceil(4*F("1.35")+F("0.8"))','m'),
('6-plan-prepay-balance','Абонемент стоит 500 рублей и включает 8 занятий, разовое занятие 80 рублей. Нужно 7 занятий. На сколько абонемент дешевле семи разовых?',60,'Семь разовых стоят 560 рублей. Абонемент дешевле на 60 рублей, хотя одно занятие останется неиспользованным.','7*80-500','m'),
('6-plan-two-length-stock','Нужно четыре отрезка по 2 м и три по 3 м. Доски длиной 5 м можно распиливать без потерь. Каково минимальное число досок?',4,'Общая длина 17 м требует не менее 4 досок. Три доски распиливаем на 2 + 3 м, четвёртая даёт оставшиеся 2 м. Четырёх достаточно.','min(n for n in range(1,10) if 5*n>=4*2+3*3)','s'),
('6-plan-cutting-obstruction','Нужно шесть отрезков по 3 м. Заготовки длиной 5 м, стыковать отрезки нельзя. Какое минимальное число заготовок нужно?',6,'Из каждой заготовки можно получить только один отрезок 3 м. Общая длина сама по себе не учитывает обрезки; нужно 6 заготовок.','ceil(6/(5//3))','s',{'tricky':True})])
